+	REQUIRE(ReadFull(*handle, block_size) == content_a);
+	REQUIRE(CountCachedBlocks(cache) == 0);
+
+	WriteTestContent(test_file.GetPath(), content_b);
+	REQUIRE(ReadFull(*handle, block_size) == content_b);
+	REQUIRE(CountCachedBlocks(cache) == 0);
+}
